            # -> LDM
            # operands
            Rn = _bits(instr, 8, 3)
            register_list = _bits(instr, 0, 8)
            # decode
            n = UInt(Rn)
            registers = concat_bits(0x0, register_list, 8)
            wback = ((registers >> n) & 1) == 0
